import React, { useState } from 'react';
import Header from '../components/Header/Header';
import BookCard from '../components/BooksList/BookCard/BookCard';
import Filters from '../components/Filters/Filters';
import './CatalogPage.css';


function CatalogPage() {
  <Filters/>
  const [searchTerm, setSearchTerm] = useState(''); // Оголошуємо searchTerm з useState

  // Функція обробки змін в полі пошуку
  const handleSearchChange = (value) => {
    setSearchTerm(value);
  };

  // Фільтрація книг за пошуковим терміном
  const filteredBooks = books.filter((book) =>
    book.title.toLowerCase().includes(searchTerm.toLowerCase().trim())
  );
  
  return (
    <div>
      <Header showSearch={true} onSearchChange={handleSearchChange} />
      
      {/* Грид для рендерингу карток книг */}
      <div className="catalog-page">
        {filteredBooks.map((book) => (
          <BookCard
            key={book.id}
            title={book.title}
            imgSrc={book.imgSrc}
            description={book.description}
          />
        ))}
      </div>
    </div>
  );
}

export default CatalogPage;
